// ValidateField validates a field and calls its OnValidate trigger
// This is equivalent to the VALIDATE function
// Usage: customer.ValidateField("Payment_terms_code", types.NewCode("30DAYS"))
func (t *ReminderTerms) ValidateField(fieldName string, value interface{}) error {
	fieldNameLower := strings.ToLower(fieldName)

	switch fieldNameLower {
	case "code":
		// Set field value
		if v, ok := value.(types.Code); ok {
			t.Code = v
		} else if v, ok := value.(string); ok {
			t.Code = types.NewCode(v)
		} else {
			return fmt.Errorf("invalid type for field code")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ReminderTermsOnValidate_Code); ok {
				if err := trg.OnValidate_Code(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "description":
		// Set field value
		if v, ok := value.(types.Text); ok {
			t.Description = v
		} else if v, ok := value.(string); ok {
			t.Description = types.NewText(v)
		} else {
			return fmt.Errorf("invalid type for field description")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ReminderTermsOnValidate_Description); ok {
				if err := trg.OnValidate_Description(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "post_interest":
		// Set field value
		if v, ok := value.(bool); ok {
			t.Post_interest = v
		} else if v, ok := value.(string); ok {
			// Handle string boolean values from JSON/frontend
			t.Post_interest = v == "true" || v == "1"
		} else {
			return fmt.Errorf("invalid type for field post_interest")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ReminderTermsOnValidate_Post_interest); ok {
				if err := trg.OnValidate_Post_interest(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "post_additional_fee":
		// Set field value
		if v, ok := value.(bool); ok {
			t.Post_additional_fee = v
		} else if v, ok := value.(string); ok {
			// Handle string boolean values from JSON/frontend
			t.Post_additional_fee = v == "true" || v == "1"
		} else {
			return fmt.Errorf("invalid type for field post_additional_fee")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ReminderTermsOnValidate_Post_additional_fee); ok {
				if err := trg.OnValidate_Post_additional_fee(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "max_no_of_reminders":
		// Set field value
		switch v := value.(type) {
		case int:
			t.Max_no_of_reminders = v
		case float64:
			t.Max_no_of_reminders = int(v)
		case string:
			if v == "" {
				t.Max_no_of_reminders = 0
			} else if i, err := strconv.Atoi(v); err == nil {
				t.Max_no_of_reminders = i
			} else {
				return fmt.Errorf("invalid integer value for field max_no_of_reminders: %s", v)
			}
		default:
			return fmt.Errorf("invalid type for field max_no_of_reminders")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ReminderTermsOnValidate_Max_no_of_reminders); ok {
				if err := trg.OnValidate_Max_no_of_reminders(t); err != nil {
					return err
				}
			}
		}
		return nil
	}

	return fmt.Errorf("field '%s' not found", fieldName)
}

